sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Converting the nominal settlement currency from current currency into USD and update that to the Nominal Settlement Amount in USD
    try {
        var inputCurrency = current.nominal_settlement_currency.getDisplayValue();
        var inputAmount = current.nominal_settlement_amount;
        var conv = new sn_currency.GlideCurrencyConverter(inputCurrency, 'USD');
        conv.setAmount(inputAmount);
        var convertValues = conv.convert();
        // MSSCUSTODY-3886 add the exception handling for the amount
        if (convertValues) {
            var convertedAmount = convertValues.getAmount();
            current.nominal_settlement_amount_in_usd = convertedAmount;

            //MSSCUSTODY-7333 - Check if Settlement Amount is not present then update the Nominal Settlement Amount
            var settlementAmount = current.settlement_amount;
            if (!settlementAmount || settlementAmount.length == 0) {
                current.settlement_amount_in_usd = convertedAmount;
            }
            // Eligible band calculation only if conversion succeeded
            var owningBusiness = current.owning_business;
            var limitGR = new GlideRecord('u_market_limit');
            limitGR.addQuery('u_market', owningBusiness);
            limitGR.orderBy('u_local_limit'); // Ascending order by local limit
            limitGR.query();

            var eligibleBand = '';
            while (limitGR.next()) {
                var localLimit = parseFloat(limitGR.u_local_limit.getCurrencyValue());
                var usdLimit = parseFloat(limitGR.u_usd_converted_limit.getCurrencyValue());

                if (inputAmount <= localLimit) {
                    eligibleBand = limitGR.u_band.toString();
                    current.eligible_band = eligibleBand;
                    break;
                }

            }
        }
    } catch (e) {
        gs.error("Custody Nominal Settlement Amound in USD: " + e.message);
    }

})(current, previous);
